const crypto = require('crypto');
const input = $input.first().json;

// Generate API key dan webhook secret
const apiKey = 'gv_' + crypto.randomBytes(32).toString('hex');
const webhookSecret = crypto.randomBytes(24).toString('base64url');

// Default config berdasarkan plan
const planConfigs = {
  starter: {
    max_contacts: 5000,
    max_keywords: 100,
    max_emails_per_month: 10000,
    features: ['crm', 'email_basic']
  },
  standard: {
    max_contacts: 25000,
    max_keywords: 500,
    max_emails_per_month: 50000,
    features: ['crm', 'email', 'seo', 'reporting']
  },
  enterprise: {
    max_contacts: 100000,
    max_keywords: 2000,
    max_emails_per_month: 200000,
    features: ['crm', 'email', 'seo', 'reporting', 'competitor', 'ai']
  }
};

const plan = input.plan_type || 'standard';
const config = planConfigs[plan] || planConfigs.standard;

return [{
  json: {
    ...input,
    api_key: apiKey,
    webhook_secret: webhookSecret,
    plan_type: plan,
    max_contacts: config.max_contacts,
    max_keywords: config.max_keywords,
    max_emails_per_month: config.max_emails_per_month,
    config: {
      features: config.features,
      timezone: input.timezone || 'Asia/Jakarta',
      notification_channel: input.slack_channel || null,
      report_recipients: input.report_emails || [input.contact_email],
      seo_domain: input.domain || null,
      competitors: input.competitors || []
    }
  }
}];

const client = $input.first().json;

// Setup default tracked keywords jika domain tersedia
const setupTasks = [];

if (client.domain) {
  setupTasks.push({
    task: 'setup_site_health',
    description: `Setup site health monitoring for ${client.domain}`
  });
}

if (client.config?.competitors?.length > 0) {
  setupTasks.push({
    task: 'setup_competitors',
    description: `Setup competitor tracking for ${client.config.competitors.length} competitors`
  });
}

setupTasks.push({
  task: 'setup_notifications',
  description: 'Configure notification channels'
});

setupTasks.push({
  task: 'send_welcome',
  description: 'Send welcome email with API credentials'
});

return [{ json: { ...client, setup_tasks: setupTasks } }];
